 public async Task ScanRoot(){Busy=true;operation=new();var pending=System.IO.Path.Combine(store.Home,Guid.NewGuid().ToString("N")+".pending");try{var normalized=System.IO.Path.GetFullPath(Root).TrimEnd('\\');if(normalized.EndsWith(':'))normalized+="\\";bool safe=Safe;try{safe|=Drives.Any(d=>normalized.StartsWith(d.Path,StringComparison.OrdinalIgnoreCase)&&d.Detail.Contains("Removable"));}catch{}var progress=new Progress<string>(Report);var result=await Task.Run(()=>new Scanner().Run(normalized,pending,safe,Exclusions,progress,operation.Token));operation.Token.ThrowIfCancellationRequested();Status="Finalizing • publishing completed snapshot";await Task.Run(()=>store.Commit(result,pending,Retention));History.Clear();foreach(var s in store.History())History.Add(s);SelectedScan=result;Status=$"Scan complete • {result.Issues:N0} skipped-path issues. See Storage issues for details. {store.LastMaintenanceWarning}";}catch(OperationCanceledException){Status="Cancelled. Previous completed snapshot preserved.";}catch(Exception e){Status="Scan failed: "+e.Message;}finally{if(File.Exists(pending))File.Delete(pending);Busy=false;operation.Dispose();operation=null;await LoadDrives();}}
