 public async Task LoadDrives(){var dispatcher=Application.Current.Dispatcher;var revision=Interlocked.Increment(ref driveRevision);try{var remembered=await dispatcher.InvokeAsync(()=>History.GroupBy(x=>x.Root,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList());var connected=new List<Entry>();var roots=await Task.Run(()=>DriveInfo.GetDrives().Select(d=>d.Name).ToArray());foreach(var root in roots){var v=await NativeWorkers.Probe(root,CancellationToken.None);connected.Add(new Entry(root,v?.Used??0,0,"drive",v==null?"Unavailable":$"{v.Type} • {v.Label} • serial {v.Serial}"));}var offline=remembered.Where(s=>!connected.Any(d=>s.Root.StartsWith(d.Path,StringComparison.OrdinalIgnoreCase)&&(s.VolumeSerial.Length==0||d.Detail.Contains(s.VolumeSerial)))).Select(s=>new Entry(s.Root,s.Bytes,0,"offline","Remembered offline • "+s.VolumeLabel+" • serial "+s.VolumeSerial+" • "+s.Date)).ToArray();await dispatcher.InvokeAsync(()=>{if(revision!=driveRevision)return;Drives.Clear();foreach(var d in connected)Drives.Add(d);foreach(var d in offline)Drives.Add(d);});}catch(Exception e){await dispatcher.InvokeAsync(()=>{if(revision==driveRevision)Status="Drive discovery unavailable: "+e.Message;});}}
